629	  /**
630	   * Set the font parameter of the context with the object properties or with charStyle
631	   * @private
632	   * @param {CanvasRenderingContext2D} ctx Context to render on
633	   * @param {Object} [charStyle] object with font style properties
634	   * @param {String} [charStyle.fontFamily] Font Family
635	   * @param {Number} [charStyle.fontSize] Font size in pixels. ( without px suffix )
636	   * @param {String} [charStyle.fontWeight] Font weight
637	   * @param {String} [charStyle.fontStyle] Font style (italic|normal)
638	   */
639	  _setTextStyles(
640	    ctx: CanvasRenderingContext2D,
641	    charStyle?: any,
642	    forMeasuring?: boolean,
643	  ) {
644	    ctx.textBaseline = 'alphabetic';
645	    if (this.path) {
646	      switch (this.pathAlign) {
647	        case CENTER:
648	          ctx.textBaseline = 'middle';
649	          break;
650	        case 'ascender':
651	          ctx.textBaseline = TOP;
652	          break;
653	        case 'descender':
654	          ctx.textBaseline = BOTTOM;
655	          break;
656	      }
657	    }
658	    ctx.font = this._getFontDeclaration(charStyle, forMeasuring);
659	  }
