661	  /**
662	   * calculate and return the text Width measuring each line.
663	   * @private
664	   * @param {CanvasRenderingContext2D} ctx Context to render on
665	   * @return {Number} Maximum width of Text object
666	   */
667	  calcTextWidth(): number {
668	    let maxWidth = this.getLineWidth(0);
669	
670	    for (let i = 1, len = this._textLines.length; i < len; i++) {
671	      const currentLineWidth = this.getLineWidth(i);
672	      if (currentLineWidth > maxWidth) {
673	        maxWidth = currentLineWidth;
674	      }
675	    }
676	    return maxWidth;
677	  }
