679	  /**
680	   * @private
681	   * @param {String} method Method name ("fillText" or "strokeText")
682	   * @param {CanvasRenderingContext2D} ctx Context to render on
683	   * @param {String} line Text to render
684	   * @param {Number} left Left position of text
685	   * @param {Number} top Top position of text
686	   * @param {Number} lineIndex Index of a line in a text
687	   */
688	  _renderTextLine(
689	    method: 'fillText' | 'strokeText',
690	    ctx: CanvasRenderingContext2D,
691	    line: string[],
692	    left: number,
693	    top: number,
694	    lineIndex: number,
695	  ) {
696	    this._renderChars(method, ctx, line, left, top, lineIndex);
697	  }
