739	              -charBox.width / 2,
740	              (-heightOfLine / this.lineHeight) * (1 - this._fontSizeFraction),
741	              charBox.width,
742	              heightOfLine / this.lineHeight,
743	            );
744	          ctx.restore();
745	        } else if (currentColor !== lastColor) {
