747	          if (this.direction === 'rtl') {
748	            drawStart = this.width - drawStart - boxWidth;
749	          }
750	          ctx.fillStyle = lastColor;
751	          lastColor &&
752	            ctx.fillRect(
753	              drawStart,
754	              lineTopOffset,
755	              boxWidth,
756	              heightOfLine / this.lineHeight,
757	            );
758	          boxStart = charBox.left;
759	          boxWidth = charBox.width;
760	          lastColor = currentColor;
761	        } else {
762	          boxWidth += charBox.kernedWidth;
763	        }
764	      }
765	      if (currentColor && !this.path) {
766	        drawStart = leftOffset + lineLeftOffset + boxStart;
767	        if (this.direction === 'rtl') {
768	          drawStart = this.width - drawStart - boxWidth;
769	        }
770	        ctx.fillStyle = currentColor;
771	        ctx.fillRect(
772	          drawStart,
773	          lineTopOffset,
774	          boxWidth,
775	          heightOfLine / this.lineHeight,
