969	  /**
970	   *
971	   * @param {String} grapheme to be measured
972	   * @param {Number} lineIndex index of the line where the char is
973	   * @param {Number} charIndex position in the line
974	   * @param {String} [prevGrapheme] character preceding the one to be measured
975	   * @returns {GraphemeBBox} grapheme bbox
976	   */
977	  _getGraphemeBox(
978	    grapheme: string,
979	    lineIndex: number,
980	    charIndex: number,
981	    prevGrapheme?: string,
982	    skipLeft?: boolean,
983	  ): GraphemeBBox {
984	    const style = this.getCompleteStyleDeclaration(lineIndex, charIndex),
985	      prevStyle = prevGrapheme
986	        ? this.getCompleteStyleDeclaration(lineIndex, charIndex - 1)
987	        : {},
988	      info = this._measureChar(grapheme, style, prevGrapheme, prevStyle);
989	    let kernedWidth = info.kernedWidth,
990	      width = info.width,
991	      charSpacing;
992	
993	    if (this.charSpacing !== 0) {
994	      charSpacing = this._getWidthOfCharSpacing();
995	      width += charSpacing;
996	      kernedWidth += charSpacing;
997	    }
998	
999	    const box: GraphemeBBox = {
1000	      width,
1001	      left: 0,
1002	      height: style.fontSize,
1003	      kernedWidth,
1004	      deltaY: style.deltaY,
1005	    };
1006	    if (charIndex > 0 && !skipLeft) {
1007	      const previousBox = this.__charBounds[lineIndex][charIndex - 1];
1008	      box.left =
1009	        previousBox.left + previousBox.width + info.kernedWidth - info.width;
1010	    }
1011	    return box;
1012	  }
