1064	  /**
1065	   * @private
1066	   * @param {CanvasRenderingContext2D} ctx Context to render on
1067	   * @param {String} method Method name ("fillText" or "strokeText")
1068	   */
1069	  _renderTextCommon(
1070	    ctx: CanvasRenderingContext2D,
1071	    method: 'fillText' | 'strokeText',
1072	  ) {
1073	    ctx.save();
1074	    let lineHeights = 0;
1075	    const left = this._getLeftOffset(),
1076	      top = this._getTopOffset();
1077	    for (let i = 0, len = this._textLines.length; i < len; i++) {
1078	      const heightOfLine = this.getHeightOfLine(i),
1079	        maxHeight = heightOfLine / this.lineHeight,
1080	        leftOffset = this._getLineLeftOffset(i);
1081	      this._renderTextLine(
1082	        method,
1083	        ctx,
1084	        this._textLines[i],
1085	        left + leftOffset,
1086	        top + lineHeights + maxHeight,
1087	        i,
1088	      );
1089	      lineHeights += heightOfLine;
1090	    }
1091	    ctx.restore();
1092	  }
