1238	  /**
1239	   * This function try to patch the missing gradientTransform on canvas gradients.
1240	   * transforming a context to transform the gradient, is going to transform the stroke too.
1241	   * we want to transform the gradient but not the stroke operation, so we create
1242	   * a transformed gradient on a pattern and then we use the pattern instead of the gradient.
1243	   * this method has drawbacks: is slow, is in low resolution, needs a patch for when the size
1244	   * is limited.
1245	   * @private
1246	   * @param {TFiller} filler a fabric gradient instance
1247	   * @return {CanvasPattern} a pattern to use as fill/stroke style
1248	   */
1249	  _applyPatternGradientTransformText(filler: TFiller) {
1250	    // TODO: verify compatibility with strokeUniform
1251	    const width = this.width + this.strokeWidth,
1252	      height = this.height + this.strokeWidth,
1253	      pCanvas = createCanvasElementFor({
1254	        width,
1255	        height,
1256	      }),
1257	      pCtx = pCanvas.getContext('2d')!;
1258	    pCanvas.width = width;
1259	    pCanvas.height = height;
1260	    pCtx.beginPath();
1261	    pCtx.moveTo(0, 0);
1262	    pCtx.lineTo(width, 0);
1263	    pCtx.lineTo(width, height);
1264	    pCtx.lineTo(0, height);
1265	    pCtx.closePath();
1266	    pCtx.translate(width / 2, height / 2);
1267	    pCtx.fillStyle = filler.toLive(pCtx)!;
1268	    this._applyPatternGradientTransform(pCtx, filler);
1269	    pCtx.fill();
1270	    return pCtx.createPattern(pCanvas, 'no-repeat')!;
1271	  }
